css:
.pipeline{border:2px solid #e9e4d3;padding:20px;background:#314149;box-shadow:9px 9px 0 #f36e45}
.request{display:flex;justify-content:space-between;align-items:center;gap:10px;border-bottom:1px solid #d7e97670;padding-bottom:17px;margin-bottom:18px}
.request code{font:12px "DM Mono",monospace;color:var(--lime)}
.response{font:12px/1.7 "DM Mono",monospace;min-height:80px;color:var(--lime);margin-top:20px;white-space:pre-wrap}
.req-headers{display:flex;flex-wrap:wrap;gap:6px 18px;font-size:11px;color:#cad9c4;margin:-6px 0 14px}
.req-headers b{color:var(--lime);font-weight:500}
.chaos{border:1px dashed #a3b0aa66;padding:12px 12px 8px;margin:0 0 14px;display:flex;flex-wrap:wrap;gap:8px}
.chaos legend{font-size:11px;color:#cad9c4;padding:0 6px}
.chaos-btn{font:600 13px "DM Sans",sans-serif;color:var(--white);background:transparent;border:1px solid #e9e4d38c;padding:7px 11px;cursor:pointer}
.chaos-btn[aria-pressed=true]{background:var(--orange);border-color:var(--orange);color:var(--ink)}
.chaos-btn[aria-pressed=true]::before{content:"⚡ "}
.chaos-btn:focus-visible,.run:focus-visible{outline:2px solid var(--lime);outline-offset:3px}
.lessons{list-style:none;padding:0;margin:12px 0 0;font-size:14px;line-height:1.5;color:#e5e3d7}
.lessons li{padding:7px 0;border-top:1px solid #a3b0aa45}
.lessons b{color:var(--lime)}
.classic-game{--green:var(--lime);--text:#eef0e6;background:#22313a;color:#eef0e6;border:2px solid var(--ink);box-shadow:5px 5px 0 #202b3066;padding:16px;margin:4px 0 14px}
.classic-game .los-try{border-top:0;padding-top:0}
.classic-game button{color:inherit}
.classic-game .timer-readout span{color:var(--green)}
.classic-game .los-try{border-top:1px solid #303932;padding-top:14px;display:grid;gap:10px}
.classic-game .los-try .timer-readout{font-size:clamp(28px,3.2vw,40px)}
.classic-game .timer-readout{font:500 clamp(36px,5vw,61px) "DM Mono",ui-monospace,monospace;letter-spacing:-.07em;color:var(--text)}
.classic-game .timer-track{height:3px;background:#303932}
.classic-game .timer-track i{display:block;background:var(--green);height:100%;width:72%;transition:none}
.classic-game .timer-actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.classic-game .timer-actions button{border:1px solid var(--green);background:#263126;color:var(--text);padding:7px 12px;font:11px "DM Mono",ui-monospace,monospace;cursor:pointer;transition:background .18s;font-size:12px}
.classic-game .timer-actions button:hover{background:#344735}
.classic-game .timer-feedback{color:#a2aa9d;font:11px/1.5 "DM Mono",ui-monospace,monospace;font-size:12px}
.classic-game .word-feature-heading{display:flex;justify-content:space-between;color:var(--green);font:600 23px "DM Mono",ui-monospace,monospace;letter-spacing:-.04em;margin-bottom:13px}
.classic-game .word-feature-heading span{font-size:18px}
.classic-game .word-mini{display:flex;flex-direction:column;gap:13px}
.classic-game .word-mini .word-feature-heading{margin-bottom:0}
.classic-game .word-mini .word-feature-heading span{font:10px "DM Mono",ui-monospace,monospace;color:#93a98d;letter-spacing:.06em}
.classic-game .word-mini-meta{display:flex;justify-content:space-between;gap:10px;color:#a7b4a2;font:10px "DM Mono",ui-monospace,monospace;font-size:12px}
.classic-game .word-mini-alphabet{display:grid;grid-template-columns:repeat(13,minmax(0,1fr));gap:3px}
.classic-game .word-mini-alphabet button{background:#253027;color:#d4dfcf;border:1px solid #465749;min-width:0;padding:6px 0;cursor:pointer;font:11px "DM Mono",ui-monospace,monospace}
.classic-game .word-mini-alphabet button:hover{background:#374838;border-color:var(--green)}
.classic-game .word-mini-tile.selected{outline:2px solid var(--green);outline-offset:2px;background:#344234}
.classic-game .word-mini-tiles{display:flex;gap:8px;justify-content:center;padding:8px 0}
.classic-game .word-mini-tile{width:min(23%,56px);height:60px;border:1px solid #60715c;background:#202820;color:#e7ece1;text-align:center;font:600 28px "DM Mono",ui-monospace,monospace;text-transform:uppercase;caret-color:var(--green);border-radius:0}
.classic-game .word-mini-tile.changed{color:var(--green);border-color:var(--green)}
.classic-game .word-mini-tile:focus{outline:2px solid var(--green);outline-offset:2px;background:#2a342a}
.classic-game .word-mini-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.classic-game .word-mini-controls button{font:11px "DM Mono",ui-monospace,monospace;cursor:pointer;padding:9px 10px;border:1px solid #6c805e;color:var(--green);background:#283126;font-size:12px}
.classic-game .word-mini-controls button+button{border-color:#465047;background:0 0;color:#bec8b7}
.classic-game .word-mini-feedback{font:11px/1.5 "DM Mono",ui-monospace,monospace;color:#c1cebb;min-height:33px;font-size:12px}
@media (max-width:600px){.classic-game .timer-actions{align-items:flex-start;flex-direction:column;gap:9px}.classic-game .timer-actions button,.classic-game .word-mini-alphabet button,.classic-game .word-mini-tile{min-height:40px}.classic-game .word-mini-tiles{flex-wrap:wrap}}
@media (max-width:550px){.classic-game .word-mini-alphabet{grid-template-columns:repeat(9,minmax(0,1fr))}}
@media (prefers-reduced-motion:reduce){.classic-game .timer-progress,.classic-game .word-mini-tile{transition:none!important}}
.classic-game .word-mini-dashboard{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.classic-game .word-mini-clock,.classic-game .word-mini-last,.classic-game .word-mini-definition,.classic-game .word-mini-history{background:#162019;border:1px solid #425343;border-radius:3px;padding:11px 13px;min-width:0}
.classic-game .word-mini-clock>span,.classic-game .word-mini-last>span,.classic-game .word-mini-definition>span,.classic-game .word-mini-history>span{display:block;color:#98ae93;letter-spacing:.1em;font:10px "DM Mono",ui-monospace,monospace;margin-bottom:5px}
.classic-game .word-mini-clock strong,.classic-game .word-mini-last strong{font:600 21px "DM Mono",ui-monospace,monospace;color:#e6eede}
.classic-game .word-mini.time-low .word-mini-clock strong{color:#e9b28d}
.classic-game .word-mini-definition>div{display:flex;gap:12px;align-items:baseline;flex-wrap:wrap}
.classic-game .word-mini-definition strong{font:650 17px "DM Mono",ui-monospace,monospace;color:#b8d5a9}
.classic-game .word-mini-definition p{font-size:12px;line-height:1.55;color:#d0dacf;margin:0;flex:1 1 170px}
.classic-game .word-mini-history>div{font:12px/1.65 "DM Mono",ui-monospace,monospace;color:#d4e3ce;overflow-wrap:anywhere}
.classic-game #word-mini-submit:disabled{opacity:.45;cursor:not-allowed}
@media(max-width:550px){.classic-game .word-mini-dashboard{gap:7px}.classic-game .word-mini-clock,.classic-game .word-mini-last,.classic-game .word-mini-definition,.classic-game .word-mini-history{padding:9px 10px}}
.sim .chaos-btn{font-size:12px;padding:6px 9px}
.seq{border-top:1px solid #d7e97670;padding-top:10px}
.lanes,.row-track{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));position:relative}
.lanes span{font:10px "DM Mono",monospace;color:#cad9c4;text-align:center;letter-spacing:.04em;padding-bottom:6px;border-bottom:1px solid #a3b0aa45;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.seq-rows{position:relative;min-height:140px;background:repeating-linear-gradient(90deg,transparent 0 calc(100%/12 - 1px),#a3b0aa2e calc(100%/12 - 1px) calc(100%/12),transparent calc(100%/12) calc(100%/6))}
.seq-empty{font-size:12px;color:var(--lime);padding:14px 0;margin:0;background:#314149}
.srow{padding:5px 0 4px;opacity:0;transform:translateY(4px);transition:opacity .25s,transform .25s}
.srow.show{opacity:1;transform:none}
.srow .lbl{display:flex;gap:7px;align-items:baseline;font:12px "DM Mono",monospace;color:#fff;padding:0 2px 3px;flex-wrap:wrap}
.srow .lbl small{color:#cad9c4;font-size:11px}
.badge{font-size:9px;letter-spacing:.08em;padding:1px 5px;color:var(--ink);font-weight:500}
.k-cmd,.badge.cmd{background:#f36e45}
.k-evt,.badge.evt{background:var(--lime)}
.k-qry,.badge.qry{background:#8fc3e6}
.k-rsp,.badge.rsp{background:#c9cfc6}
.badge.step{background:#fffaf0}
.row-track{height:12px}
.arrow{position:relative;height:2px;top:5px;align-self:start}
.arrow::after{content:"";position:absolute;top:-4px;border:5px solid transparent}
.arrow.r::after{right:-2px;border-left-color:inherit;border-right:0}
.arrow.l::after{left:-2px;border-right-color:inherit;border-left:0}
.arrow.cmd{background:#f36e45;border-color:#f36e45}
.arrow.evt{background:var(--lime);border-color:var(--lime)}
.arrow.qry{background:#8fc3e6;border-color:#8fc3e6}
.arrow.rsp{background:#c9cfc6;border-color:#c9cfc6}
.arrow.async{background:repeating-linear-gradient(90deg,var(--lime) 0 6px,transparent 6px 10px)}
.arrow.bad{background:repeating-linear-gradient(90deg,#f36e45 0 4px,transparent 4px 8px)}
.sdot{width:12px;height:12px;border-radius:50%;justify-self:center;align-self:center;border:2px solid #fffaf0}
.sdot.ok{background:var(--lime)}
.sdot.warn{background:#f36e45}
.legend{display:flex;flex-wrap:wrap;gap:4px 12px;font-size:10px;color:#cad9c4;margin-top:8px;align-items:center}
.legend i{display:inline-block;width:14px;height:3px;margin-right:4px;vertical-align:middle}
.sim-panels{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}
.sim-panels .mono{font-size:10px;color:#cad9c4;letter-spacing:.06em}
.estore{list-style:none;margin:6px 0 0;padding:8px 10px;min-height:90px;background:#22313a;border:1px solid #a3b0aa45;font:11px/1.7 "DM Mono",monospace;color:#e6eadf;counter-reset:ev}
.estore li{counter-increment:ev}
.estore li::before{content:"#" counter(ev) " ";color:var(--lime)}
.estore li.dupe{color:#ffb999}
.rmodel{margin:6px 0 0;padding:8px 10px;min-height:90px;background:#22313a;border:1px solid #a3b0aa45;font:11px/1.6 "DM Mono",monospace;color:#8fc3e6;white-space:pre-wrap;overflow-wrap:anywhere}
.rmodel.stale{color:#ffb999}
@media(max-width:760px){.lanes span{font-size:8px;letter-spacing:0}.sim-panels{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.srow{transition:none}}
@media(max-width:760px){.play-card .classic-game{display:none}.play-card.is-open .classic-game{display:block}}
.sim-toggle{display:none}
@media(max-width:760px){.sim-toggle{display:inline-flex;font:700 14px "DM Sans",sans-serif;padding:12px 16px;border:2px solid var(--lime);background:transparent;color:var(--lime);cursor:pointer;margin:6px 0 4px}.demo-grid:not(.is-open) .sim{display:none}.demo-grid.is-open .sim-toggle{display:none}}
.sim-toggle:focus-visible{outline:3px solid var(--lime);outline-offset:3px}

