(()=>{
const timerButton=document.getElementById('timer-action'),timerDisplay=document.getElementById('timer-display'),timerProgress=document.getElementById('timer-progress'),timerFeedback=document.getElementById('timer-feedback');
let timerStart=0,timerRunning=false,timerFrame=0;
const formatTime=ms=>{const hundredths=Math.floor(ms/10),whole=Math.floor(hundredths/100),fraction=String(hundredths%100).padStart(2,'0');return '00:'+String(whole).padStart(2,'0')+'<span>.'+fraction+'</span>'};
const paintTimer=ms=>{timerDisplay.innerHTML=formatTime(ms);timerProgress.style.width=Math.min(ms/5000*100,100)+'%'};
const tick=()=>{if(!timerRunning)return;paintTimer(performance.now()-timerStart);timerFrame=requestAnimationFrame(tick)};
timerButton.addEventListener('click',()=>{
 if(!timerRunning){timerRunning=true;timerStart=performance.now();timerButton.textContent='Stop timer';timerFeedback.textContent='Aim for 5.00 seconds';paintTimer(0);timerFrame=requestAnimationFrame(tick);return}
 timerRunning=false;cancelAnimationFrame(timerFrame);const elapsed=performance.now()-timerStart;paintTimer(elapsed);const offset=Math.abs(elapsed-5000);timerFeedback.textContent=offset<50?'Almost perfect!':offset<250?'Very close!':'Off by '+(offset/1000).toFixed(2)+'s. Try again.';timerButton.textContent='Try again';
});
