const miniDefinitions={TALK:'To speak or discuss something.',MAIL:'Letters and parcels sent or received.',WIND:'Moving air.',GAME:'An activity played for enjoyment.',FIRE:'Heat and light produced by burning.',SAND:'Tiny grains of rock found on beaches.'};
const miniDefinitionCache=new Map(Object.entries(miniDefinitions));
async function miniShowMeaning(word){
 miniCurrentLabel.textContent=word;
