 let definition='';
 try{
  const response=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(clean));
  if(response.ok){
   const entries=await response.json();
   definition=(entries?.[0]?.meanings||[]).flatMap(item=>item.definitions||[]).map(item=>item.definition).find(Boolean)||'';
  }
 }catch(error){}
 if(!definition){
  try{
   const response=await fetch('https://api.datamuse.com/words?sp='+encodeURIComponent(clean)+'&md=d&max=8');
   if(response.ok){
    const entries=await response.json();
    const exact=entries.find(item=>item.word?.toLowerCase()===clean);
    const raw=exact?.defs?.[0]||'';
    definition=raw.includes('\t')?raw.slice(raw.indexOf('\t')+1).trim():raw.trim();
   }
  }catch(error){}
 }
 if(request!==miniDefinitionRequest)return;
 if(definition){miniDefinitionCache.set(word,definition);miniMeaning.textContent=definition}
